// Rivals — PART-2-LAYER-C procedural rival system.
//
// Rivals are PROCEDURALLY GENERATED at game start (10 at cell stage) and
// at each stage transition (3-5 new rivals + 3-5 carried forward from the
// previous stage). Names are generated by combining 3 name lists:
//   "The {Modifier} {Noun} of {Concept}"
//
// ASSIMILATION MECHANICS (per user spec):
//   - Assimilation requires large amounts of military_power AND culture.
//   - Each countered raid decreases the military requirement.
//   - Each successful trade decreases the culture requirement.
//
// POPULATION TRACKING: each rival has a `population` that grows over time.
// At Cell→Creature, the top 5 rivals by population are carried forward;
// the remaining 5 are hidden. From Creature onwards, all rivals are
// interactable (no more hiding).

import type { StageId, ResourceId } from "../state/types";
import { STAGE_RESOURCES } from "./resources";

// ============================================================
// NAME GENERATION — 3 lists combined into "The {Modifier} {Noun} of {Concept}"
// ============================================================

